/**
 * The field entity's sub-type table. Fields are a real sub-entity — 13
 * terraform resource types sharing one emission/extraction shape — so the
 * per-sub-type knowledge is one ROW here, not one file: the only thing that
 * varies between an html field and a number field is this mapping triple.
 * A sub-type that grows real per-kind logic graduates to its own file under
 * this directory (the automation task/ pattern).
 */
export const FIELD_SUB_TYPES = [
    { typeKey: "calculated", resourceType: "elementum_calculated_field", authoringType: "CALCULATED", implemented: true },
    { typeKey: "text", resourceType: "elementum_text_field", authoringType: "TEXT", implemented: true },
    { typeKey: "html", resourceType: "elementum_longtext_field", authoringType: "RICH_TEXT", implemented: true },
    { typeKey: "number", resourceType: "elementum_number_field", authoringType: "NUMBER", implemented: true },
    { typeKey: "decimal", resourceType: "elementum_decimal_field", authoringType: "DECIMAL", implemented: true },
    { typeKey: "bool", resourceType: "elementum_boolean_field", authoringType: "BOOLEAN", implemented: true },
    { typeKey: "date", resourceType: "elementum_date_field", authoringType: "DATE", implemented: true },
    { typeKey: "dateTime", resourceType: "elementum_datetime_field", authoringType: "DATETIME", implemented: true },
    { typeKey: "user", resourceType: "elementum_user_field", authoringType: "USER", implemented: true },
    { typeKey: "group", resourceType: "elementum_group_field", authoringType: "GROUP", implemented: true },
    { typeKey: "attachment", resourceType: "elementum_attachment_field", authoringType: "ATTACHMENT", implemented: true },
    { typeKey: "json", resourceType: "elementum_json_field", authoringType: "JSON", implemented: true },
    {
        typeKey: "picklist",
        resourceType: "elementum_dropdown_field",
        authoringType: "PICKLIST",
        hasOptions: true,
        implemented: true,
    },
    {
        typeKey: "multiPicklist",
        resourceType: "elementum_multiselect_field",
        authoringType: "MULTI_PICKLIST",
        hasOptions: true,
        implemented: true,
    },
    // related_object_id/related_label_field_id/auto_relate are handled
    // specially in fieldFromTf/fieldToTf (see hasRelation below), not via the
    // generic default_value/options handling other sub-types share.
    {
        typeKey: "relation",
        resourceType: "elementum_relation_field",
        authoringType: "RELATION",
        hasRelation: true,
        implemented: true,
    },
];
export const SUB_TYPE_BY_TYPE_KEY = new Map(FIELD_SUB_TYPES.map((t) => [t.typeKey, t]));
export const SUB_TYPE_BY_RESOURCE = new Map(FIELD_SUB_TYPES.map((t) => [t.resourceType, t]));
/** Keyed by the canonical authoring type (e.g. "TEXT") — what a `FieldRef` token carries as `fieldType`. */
export const SUB_TYPE_BY_AUTHORING_TYPE = new Map(FIELD_SUB_TYPES.map((t) => [t.authoringType, t]));
export const FIELD_RESOURCE_TYPES = FIELD_SUB_TYPES.map((t) => t.resourceType);
/** Attributes `fieldFromTf` understands — anything else is dialect growth, reported loudly. */
export const KNOWN_FIELD_ATTRS = new Set([
    "object_id",
    "name",
    "required",
    "required_on_close",
    "show_on_create",
    "lock_on_create",
    "description",
    "column_name",
    "default_value",
    "options",
    "field_role",
    "related_object_id",
    "related_label_field_id",
    "auto_relate",
    "dynamic_config",
    "static_config",
    "decimal_places",
    "currency",
    "percentage",
    "delimiter",
    "calculation",
    "calculation_type",
    "include_type",
    "picklist_field_id",
    "media_types",
]);
